function portPid() {
  try {
    const out = execSync('powershell -NoProfile -Command "(Get-NetTCPConnection -LocalPort 3100 -State Listen -ErrorAction SilentlyContinue | Select-Object -First 1).OwningProcess"', { encoding: "utf8" }).trim();
    return out ? Number(out) : null;
  } catch { return null; }
}
function starten() {
  // bewährte Startmethode: PowerShell Start-Process öffnet ein eigenes, minimiertes Fenster mit dem Dev-Server
  const ps = `Start-Process -FilePath cmd.exe -ArgumentList '/k','title OekoInvest Dev-Server && npm run dev' -WorkingDirectory '${PROJEKT}' -WindowStyle Minimized`;
  // synchron aufrufen: als abgekoppelter, versteckter Prozess startet PowerShell unter Windows nicht zuverlässig
  const r = spawnSync("powershell.exe", ["-NoProfile", "-Command", ps], { encoding: "utf8" });
  if (r.status !== 0) log(`Start fehlgeschlagen: ${(r.stderr || r.error || "").toString().slice(0, 200)}`);
  status.neustarts++; status.letzterNeustart = new Date().toISOString();
  log("Dev-Server gestartet");
}
async function pruefen() {
  const t0 = Date.now();
  try {
    const r = await fetch(PRUEF_URL, { signal: AbortSignal.timeout(60000) });
    status.antwortMs = Date.now() - t0;
    // Zusätzlich eine echte Seite prüfen: ein kaputter Turbopack-Cache liefert dort 500, robots.txt aber 200
    // Nur der typische Turbopack-Cache-Fehler („Module not found … turbopack“) zählt – Code-Fehler der Agenten
    // (z. B. mitten in einem Umbau) beheben die Agenten selbst; ein Neustart würde sie nur stören.
    const s = await fetch(SEITEN_URL, { signal: AbortSignal.timeout(120000) })
      .then(async (x) => {
        if (x.status !== 500) return x.status;
        return /Module not found[\s\S]{0,300}turbopack/i.test(await x.text()) ? 500 : 599; // 599 = Code-Fehler, kein Neustart
      }, () => 0);
    if (s === 599) status.hinweis = "Seiten liefern 500 durch einen Code-Fehler (kein Cache-Problem) – kein Neustart";
    else delete status.hinweis;
    // Liefert sogar robots.txt 500 (reiner „Internal Server Error“ überall), ist der Server-Zustand
    // bzw. Cache kaputt, kein Seitencode – das behebt nur ein Neustart mit leerem .next
    const allesKaputt = r.status === 500 && (s === 500 || s === 599);
    if ((r.ok && s === 500) || allesKaputt) {
      status.cache500 = (status.cache500 || 0) + 1;
      status.zustand = `Seiten liefern 500 (${status.cache500}/3, evtl. kaputter Cache)`;
      if (status.cache500 >= 3) {
        log("Seiten liefern dauerhaft 500 – Server beenden, .next-Cache löschen, neu starten");
        const pid = portPid();
        if (pid) { try { execSync(`taskkill /PID ${pid} /T /F`); } catch {} }
        await new Promise((res) => setTimeout(res, 4000));
        try { execSync(`powershell -NoProfile -Command "Remove-Item -Recurse -Force '${PROJEKT}\\.next' -ErrorAction SilentlyContinue"`); } catch {}
        starten();
        status.cache500 = 0;
        await new Promise((res) => setTimeout(res, 90000));
      }
    } else {
      status.cache500 = 0;
      status.zustand = r.ok ? "läuft" : `antwortet mit ${r.status}`;
    }
    status.fehlerInFolge = 0;
  } catch {
    status.fehlerInFolge++;
    status.antwortMs = null;
    const pid = portPid();
    if (!pid) {
      status.zustand = "abgestürzt – Neustart";
      log("Kein Prozess auf Port 3100 – Neustart");
      starten();
      await new Promise((r) => setTimeout(r, 60000));
    } else if (status.fehlerInFolge >= 3) {
      status.zustand = "hängt – wird neu gestartet";
      log(`Server hängt (PID ${pid}) – beenden und neu starten`);
      try { execSync(`taskkill /PID ${pid} /T /F`); } catch {}
      await new Promise((r) => setTimeout(r, 3000));
      starten();
      status.fehlerInFolge = 0;
      await new Promise((r) => setTimeout(r, 60000));
    } else {
      status.zustand = `keine Antwort (${status.fehlerInFolge}/3, kompiliert evtl.)`;
    }
  }
  status.letztePruefung = new Date().toISOString();
  speichern();
}

// src/app/sitemap.js
//
// Sitemap der ÖkoInvest-Website unter /sitemap.xml (wie vor Welle 2), Ländermodell:
//  - jede indexierbare gemeinsame Seite aus dem Register (src/lib/land/seiten.js), ohne Entwürfe
//    (ENTWURFSSEITEN in src/lib/indexsteuerung.js), mit Regionsseiten,
//  - dazu jede Länderfassung (/de, /at, /ch) mit ECHTEM eigenem Länderinhalt (LAENDERINHALT),
//    jeweils mit hreflang-Cluster (src/lib/land/sitemaps.js) – Länderfassungen ohne eigenen
//    Inhalt tragen noindex und fehlen hier,
//  - die übersetzten englischen Fassungen (/en/…, Register src/lib/sprache/seiten.js) mit demselben
//    hreflang-Cluster, alle Ratgeber-Artikel und, sofern das Plattform-Backend verfügbar
//    ist, die öffentlichen Exposés der Projektbörse.
//
// Portal, Login/Registrierung, /angebot, /einladung, /termin/verwalten, /bericht, /p und die
// Entwürfe unter /bedingungen gehören nicht in die Sitemap bzw. sind über robots.txt gesperrt.

import { alleArtikel, artikelPfad } from "@/lib/ratgeber";
import { LEXIKON_STAND } from "@/data/lexikon";
import { abs } from "@/data/site";
import { sichtbareProjekte } from "@/lib/boerse/sichtbarkeit";
import { START, SPRACHMODELL, seitenEintraege } from "@/lib/land/sitemaps";
import { fassungIndexierbar, hreflang, seitenPfad } from "@/lib/land/pfad";

/**
 * Öffentliche Exposés der Projektbörse aus dem Plattform-Backend
 * (src/lib/plattform/backend: backend().boerse(null, filter) -> { projekte, demo }).
 * Fehlt das Backend, ist es nicht konfiguriert (HTTP 503) oder antwortet es
 * nicht, bleibt die Sitemap trotzdem vollständig – nur ohne Projektseiten.
 * Demo-Daten landen bewusst nie in der Sitemap.
 */
async function projektEintraege() {
  try {
    const modul = await import("@/lib/plattform/backend");
    const impl = typeof modul.backend === "function" ? modul.backend() : modul;
    if (typeof impl?.boerse !== "function") return [];
    const antwort = await Promise.race([
      impl.boerse(null, {}),
      new Promise((_, nein) => setTimeout(() => nein(new Error("Zeitüberschreitung")), 5000)),
    ]);
    if (antwort?.demo) return [];
    const liste = Array.isArray(antwort) ? antwort : antwort?.projekte || [];
    // QM Welle 1: Test- und Demo-Datensätze nie in die Sitemap (src/lib/boerse/sichtbarkeit.js)
    return sichtbareProjekte(liste, { demo: false })
      .filter((p) => p && typeof p.slug === "string" && /^[a-z0-9-]+$/.test(p.slug))
      .map((p) => {
        const d = new Date(p.geaendertAm || p.aktualisiert || p.veroeffentlichtAm || p.modified || START);
        return {
          url: abs(`/projektboerse/${p.slug}`),
          lastModified: Number.isNaN(d.getTime()) ? START : d,
          changeFrequency: "weekly",
          priority: 0.6,
        };
      });
  } catch {
    return [];
  }
}

export default async function sitemap() {
  const seiten = seitenEintraege({ lexikonStand: LEXIKON_STAND });
  // Ratgeber-Artikel; einzeln übersetzte (UEBERSETZT_EINZELN) zusätzlich unter /en mit hreflang-Cluster
  const ratgeber = alleArtikel().flatMap((a) => {
    const pfad = artikelPfad(a.slug);
    const basis = { lastModified: new Date(a.aktualisiert), changeFrequency: "monthly", priority: 0.7 };
    if (!fassungIndexierbar(pfad, null, "en")) return [{ url: abs(pfad), ...basis }];
    const alternates = { languages: hreflang(pfad) };
    return [
      { url: abs(pfad), ...basis, alternates },
      { url: abs(seitenPfad(pfad, null, "en")), ...basis, lastModified: SPRACHMODELL, alternates },
    ];
  });
  return [...seiten, ...ratgeber, ...(await projektEintraege())];
}
// src/app/robots.js – robots.txt der ÖkoInvest-Website
//
// Regeln stehen in src/lib/indexsteuerung.js (robotsRegeln, getestet in
// src/lib/indexsteuerung.test.mjs). Kurzfassung nach Entscheidung E5:
//
//  - Alle Crawler ("*"), darunter Googlebot, Bingbot und die Such- und Abruf-
//    crawler der KI-Dienste (OAI-SearchBot, ChatGPT-User, PerplexityBot,
//    Claude-SearchBot, Claude-User): öffentliche Seiten erlaubt; /api/,

