const fs=require("fs");
const L=fs.readFileSync("http.jsonl","utf8").trim().split("\n").map(JSON.parse);
const m=new Map();L.forEach(e=>{ if(!e.u.startsWith("/")) return; m.set(e.u,e)});
const a=[...m.values()];
const pre=(u)=>{const x=u.match(/^(\/en)?(\/(de|at|ch))?(?=\/|$)/);return {en:!!x[1],land:x[3]||null,key:u.slice(x[0].length)||"/"}};
const langSoll=(p)=>p.en?"en":p.land?{de:"de-DE",at:"de-AT",ch:"de-CH"}[p.land]:"de";
const bad=[];
for(const e of a){
  if(e.s!==200){bad.push(`STATUS ${e.u} ${e.s||e.err} ${e.loc||""}`);continue}
  const p=pre(e.u);
  if(e.lang!==langSoll(p)) bad.push(`LANG ${e.u} ${e.lang} soll ${langSoll(p)}`);
  if(e.canon!==e.u) bad.push(`CANON ${e.u} -> ${e.canon}`);
  const sw=new Set(); for(const en of [false,true]) for(const l of [null,"de","at","ch"]) sw.add(((en?"/en":"")+(l?"/"+l:"")+(p.key==="/"?"":p.key))||"/");
  const fremd=e.fremd.filter(h=>!sw.has(h) && !(h==="/en"||h==="/en/"+p.land));
  if(fremd.length) bad.push(`LINK ${e.u}: ${fremd.join(" ")}`);
  // hreflang back-check
  for(const h of e.hre){const [hl,url]=h.split("=");const z=m.get(url); if(!z) continue; if(z.s===200 && !z.hre.includes(h)) bad.push(`HREFLANG ${e.u} nennt ${h}, aber ${url} nicht zurück`); if(z.s===200 && !z.hre.some(x=>x.endsWith("="+e.u))) bad.push(`HREFLANG-RUECK ${url} verweist nicht auf ${e.u}`);}
  if(e.hre.length && !e.hre.some(h=>h.endsWith("="+e.u))) bad.push(`HREFLANG-SELBST ${e.u} fehlt in eigenem Cluster`);
  if(e.hre.length && !e.hre.some(h=>h.startsWith("x-default="))) bad.push(`XDEFAULT ${e.u}`);
}
console.log(a.length+" Seiten; Befunde: "+bad.length);
console.log(bad.join("\n"));
console.log("--- EN-Hinweis (nicht übersetzt):", a.filter(e=>e.enHinweis).map(e=>e.u).join(" "));
console.log("--- DE-Seiten mit EN-Hinweis:", a.filter(e=>e.enHinweis&&!e.u.startsWith("/en")).map(e=>e.u).join(" "));
console.log("--- cache-control /:", (m.get("/")||{}).cc);
EOF
node analyse.cjs 2>&1 | head -80

