// Ausschnitt-Aufnahme: node qm-crop.mjs <basis> <out> <breite> <pfad>@<selektor> ...
import { chromium } from "playwright";
import { mkdirSync } from "node:fs";
const [basis, out, breite, ...ziele] = process.argv.slice(2);
mkdirSync(out, { recursive: true });
const browser = await chromium.launch();
const ctx = await browser.newContext({ reducedMotion: "reduce" });
const page = await ctx.newPage();
const w = Number(breite);
await page.setViewportSize({ width: w, height: w < 700 ? 844 : 900 });
for (const z of ziele) {
  const [pfad, sel] = z.split("@");
  try {
    const r = await page.goto(basis + pfad, { waitUntil: "load", timeout: 300000 });
    await page.locator("button", { hasText: /Nur notwendige|Only necessary/ }).first().click({ timeout: 3000 }).catch(() => {});
    await page.evaluate(async () => { for (let y = 0; y < document.body.scrollHeight; y += 400) { window.scrollTo(0, y); await new Promise((r) => setTimeout(r, 40)); } });
    await page.waitForTimeout(600);
    const el = page.locator(sel).first();
    await el.scrollIntoViewIfNeeded();
    const name = (pfad + "_" + sel).replace(/[^a-z0-9]+/gi, "_").replace(/^_|_$/g, "");
    await el.screenshot({ path: `${out}/w${w}-${name}.png` });
    const breiteDoc = await page.evaluate(() => document.documentElement.scrollWidth);
    console.log(`OK w${w} ${pfad} ${sel} status=${r?.status()} breite=${breiteDoc}`);
  } catch (e) {
    console.log(`!! w${w} ${pfad} ${sel} ${String(e).slice(0, 140)}`);
  }
}
await browser.close();
// Abschnittsbilder für die Länderinhalte (Gruppe 2): je Pfad und Breite ausgewählte Abschnitte als Bild.
